function PosPage(){const items=[['Veg Burger',149,'Popular'],['Margherita Pizza',299,'Main'],['Paneer Wrap',189,'Snacks'],['Cold Coffee',99,'Beverages'],['Masala Chai',49,'Beverages'],['Masala Fries',129,'Snacks'],['Chole Bhature',169,'Main'],['Gulab Jamun',79,'Desserts']];const[cat,setCat]=useState('All');const[cart,setCart]=useState([{n:'Veg Burger',p:149,q:2},{n:'Cold Coffee',p:99,q:1}]);const[pay,setPay]=useState('UPI');const add=x=>setCart(c=>{const f=c.find(i=>i.n===x[0]);return f?c.map(i=>i.n===x[0]?{...i,q:i.q+1}:i):[...c,{n:x[0],p:x[1],q:1}]});const total=cart.reduce((s,x)=>s+x.p*x.q,0);const sales=[{h:'10 AM',v:4800},{h:'12 PM',v:9200},{h:'2 PM',v:12400},{h:'4 PM',v:9800},{h:'6 PM',v:15100},{h:'8 PM',v:18700}];return <Layout><PageHero eyebrow="TriNova POS" title={<>Fast billing. Better control. <span className="grad">Live sales visibility.</span></>} copy="A complete POS for restaurants, cafes, sweet shops, retail, grocery and pharmacies."/><section className="section"><div className="wrap"><div className="posApp"><aside>{['All','Popular','Beverages','Snacks','Main','Desserts'].map(x=><button className={cat===x?'active':''} onClick={()=>setCat(x)} key={x}>{x}</button>)}</aside><div className="posCenter"><div className="posSearch"><Search/>Search items...</div><div className="posItems">{items.filter(x=>cat==='All'||x[2]===cat).map(x=><button onClick={()=>add(x)} key={x[0]}><b>{x[0]}</b><span>₹{x[1]}</span></button>)}</div></div><div className="posCart"><h3>Order #1042</h3>{cart.map((x,i)=><div className="cartLine" key={x.n}><span>{x.n}<small>× {x.q}</small></span><b>₹{x.p*x.q}</b></div>)}<div className="cartTotal"><span>Total</span><strong>₹{Math.round(total*1.05).toLocaleString('en-IN')}</strong></div><div className="payRow">{['UPI','Cash','Card'].map(x=><button className={pay===x?'active':''} onClick={()=>setPay(x)} key={x}>{x}</button>)}</div><button className="checkout"><ReceiptText/>Print Bill / Token</button></div></div></div></section><section className="section soft"><div className="wrap"><div className="dashboardTitle"><div><Eyebrow>POS Analytics</Eyebrow><h2>Owner dashboard</h2></div><span>Today · Live</span></div><div className="kpiGrid four"><Kpi label="Net Sales" value="₹84,250" trend="+14.2%" icon={CircleDollarSign}/><Kpi label="Orders" value="286" trend="+8.4%" icon={ShoppingCart}/><Kpi label="Avg Bill" value="₹294" trend="+5.1%" icon={ReceiptText}/><Kpi label="Low Stock" value="12" trend="action needed" icon={Boxes}/></div><div className="chartGrid"><div className="chartCard"><div className="chartTitle"><b>Hourly sales</b><span>₹</span></div><ResponsiveContainer width="100%" height={260}><AreaChart data={sales}><CartesianGrid strokeDasharray="3 3" stroke="#dbeafe"/><XAxis dataKey="h"/><YAxis hide/><Tooltip/><Area dataKey="v" stroke="#3b82f6" fill="#dbeafe" strokeWidth={3}/></AreaChart></ResponsiveContainer></div><div className="chartCard"><div className="chartTitle"><b>Payment mix</b><span>Today</span></div><ResponsiveContainer width="100%" height={260}><PieChart><Pie data={[{n:'UPI',v:62},{n:'Cash',v:24},{n:'Card',v:14}]} dataKey="v" nameKey="n" innerRadius={55} outerRadius={85}>{[0,1,2].map((i)=><Cell key={i} fill={COLORS[i]}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer></div></div></div></section></Layout>}

